create extension if not exists pgcrypto;
create type public.profile_type as enum ('spotify','manual','simulated');
create type public.connection_status as enum ('invited','connecting','ready','error');
create table public.sessions(id uuid primary key default gen_random_uuid(),invite_code text not null unique default encode(gen_random_bytes(16),'hex'),host_user_id uuid not null default auth.uid(),occasion text not null,target_duration_ms integer not null check(target_duration_ms between 900000 and 43200000),energy_style text not null default 'build',familiarity text not null default 'Balanced',clean_lyrics boolean not null default true,artist_repeat_limit smallint not null default 2 check(artist_repeat_limit between 1 and 5),generated_title text,edited_title text,status text not null default 'planning',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.participants(id uuid primary key default gen_random_uuid(),session_id uuid not null references public.sessions on delete cascade,user_id uuid default auth.uid(),display_name text not null,avatar_url text,profile_type public.profile_type not null,connection_status public.connection_status not null default 'invited',spotify_user_id text,sort_order smallint not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(session_id,user_id));
create table public.taste_profiles(id uuid primary key default gen_random_uuid(),participant_id uuid not null unique references public.participants on delete cascade,broad_genres text[] not null default '{}',representative_artists jsonb not null default '[]',spotify_top_artist_ids text[] not null default '{}',spotify_top_track_ids text[] not null default '{}',familiarity_preference text not null default 'Balanced',approved_for_session boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.invitations(id uuid primary key default gen_random_uuid(),session_id uuid not null references public.sessions on delete cascade,code text not null unique default encode(gen_random_bytes(20),'hex'),revoked_at timestamptz,expires_at timestamptz not null default now()+interval '7 days',created_at timestamptz not null default now());
create table public.track_rules(id uuid primary key default gen_random_uuid(),session_id uuid not null references public.sessions on delete cascade,rule_type text not null check(rule_type in('must_play','excluded_track','excluded_artist')),spotify_id text not null,spotify_uri text,display_name text not null,unique(session_id,rule_type,spotify_id));
create table public.playlist_versions(id uuid primary key default gen_random_uuid(),session_id uuid not null references public.sessions on delete cascade,generation_seed integer not null,title text not null,description text,created_at timestamptz not null default now());
create table public.playlist_tracks(id uuid primary key default gen_random_uuid(),playlist_version_id uuid not null references public.playlist_versions on delete cascade,spotify_track_id text not null,spotify_uri text,title text not null,artist_name text not null,position integer not null,locked boolean not null default false,explanation text,unique(playlist_version_id,position));
create index participants_session_idx on public.participants(session_id);create index invitations_code_idx on public.invitations(code);create index playlist_versions_session_idx on public.playlist_versions(session_id,created_at desc);create index playlist_tracks_version_idx on public.playlist_tracks(playlist_version_id,position);
alter table public.sessions enable row level security;alter table public.participants enable row level security;alter table public.taste_profiles enable row level security;alter table public.invitations enable row level security;alter table public.track_rules enable row level security;alter table public.playlist_versions enable row level security;alter table public.playlist_tracks enable row level security;
create or replace function public.is_session_member(requested_session uuid)returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from participants where session_id=requested_session and user_id=auth.uid()) or exists(select 1 from sessions where id=requested_session and host_user_id=auth.uid())$$;
create policy sessions_member_read on public.sessions for select using(public.is_session_member(id));create policy sessions_host_write on public.sessions for all using(host_user_id=auth.uid()) with check(host_user_id=auth.uid());
create policy participants_member_read on public.participants for select using(public.is_session_member(session_id));create policy participants_self_write on public.participants for all using(user_id=auth.uid()) with check(user_id=auth.uid());create policy participants_host_delete on public.participants for delete using(exists(select 1 from sessions where sessions.id=session_id and sessions.host_user_id=auth.uid()));
create policy taste_member_approved_read on public.taste_profiles for select using(approved_for_session and public.is_session_member((select session_id from participants where id=participant_id)));create policy taste_self_write on public.taste_profiles for all using(exists(select 1 from participants where participants.id=participant_id and participants.user_id=auth.uid())) with check(exists(select 1 from participants where participants.id=participant_id and participants.user_id=auth.uid()));
create policy invitation_host_all on public.invitations for all using(exists(select 1 from sessions where sessions.id=session_id and sessions.host_user_id=auth.uid())) with check(exists(select 1 from sessions where sessions.id=session_id and sessions.host_user_id=auth.uid()));
create policy rules_member_read on public.track_rules for select using(public.is_session_member(session_id));create policy rules_host_write on public.track_rules for all using(exists(select 1 from sessions where sessions.id=session_id and sessions.host_user_id=auth.uid())) with check(exists(select 1 from sessions where sessions.id=session_id and sessions.host_user_id=auth.uid()));
create policy versions_member_read on public.playlist_versions for select using(public.is_session_member(session_id));create policy versions_host_write on public.playlist_versions for all using(exists(select 1 from sessions where sessions.id=session_id and sessions.host_user_id=auth.uid())) with check(exists(select 1 from sessions where sessions.id=session_id and sessions.host_user_id=auth.uid()));
create policy playlist_tracks_member_read on public.playlist_tracks for select using(public.is_session_member((select session_id from playlist_versions where id=playlist_version_id)));create policy playlist_tracks_host_write on public.playlist_tracks for all using(exists(select 1 from playlist_versions join sessions on sessions.id=playlist_versions.session_id where playlist_versions.id=playlist_version_id and sessions.host_user_id=auth.uid())) with check(exists(select 1 from playlist_versions join sessions on sessions.id=playlist_versions.session_id where playlist_versions.id=playlist_version_id and sessions.host_user_id=auth.uid()));
create or replace function public.get_session_by_invite(requested_code text)returns setof public.sessions language sql stable security definer set search_path=public as $$select sessions.* from sessions where sessions.invite_code=requested_code and sessions.status<>'closed' limit 1$$;
alter publication supabase_realtime add table public.participants,public.playlist_versions;
